import os
import requests
from typing import List, Dict, Optional

def query_datadog_logs(
    query: str,
    time_from: str,
    time_to: str,
    api_key: Optional[str] = None,
    app_key: Optional[str] = None,
    site: str = "datadoghq.com",
    limit: int = 50
) -> List[Dict]:
    api_key = api_key or os.getenv("DD_API_KEY")
    app_key = app_key or os.getenv("DD_APP_KEY")

    if not api_key or not app_key:
        raise ValueError("Datadog DD_API_KEY and DD_APP_KEY must be provided.")

    url = f"https://api.{site}/api/v2/logs/events/search"
    headers = {
        "Accept": "application/json",
        "Content-Type": "application/json",
        "DD-API-KEY": api_key,
        "DD-APPLICATION-KEY": app_key
    }

    payload = {
        "data": {
            "type": "logs_list_request",
            "attributes": {
                "query": query,
                "time": {
                    "from": time_from,
                    "to": time_to
                },
                "sort": "-timestamp",
                "page": {
                    "limit": limit
                }
            }
        }
    }

    response = requests.post(url, json=payload, headers=headers)
    response.raise_for_status()

    events = response.json().get("data", [])
    return [event.get("attributes", {}) for event in events]
